styl:
.iq-combo-promo-steps--brad-full{border-radius:32px!important}
.iq-combo-promo-steps--white-bg{background-color:#fff}
.iq-combo-promo-steps--gray-block{padding:24px;background:#f9f9f9;border-radius:12px}
.iq-combo-promo-steps--w100{width:100%}
.iq-combo-promo-steps--m-w{min-width:78px!important;width:78px!important;vertical-align:middle}
.iq-combo-promo-steps--w-a{width:auto!important;vertical-align:middle}
.iq-combo-promo-steps--number{font-family:Helvetica!important;font-weight:700;background:#ececed;width:54px;max-height:54px;border-radius:16px;color:#393a44;font-size:24px;line-height:24px;padding:15px 0;text-align:center}
.iq-combo-promo-steps--middle-title{font-family:Helvetica!important;font-weight:700;font-size:32px;line-height:42px;color:#393a44}
@media screen and (max-width:600px){.iq-combo-promo-steps--middle-title{font-size:28px!important;line-height:34px!important}.iq-combo-promo-steps--text-pad-small{padding-left:20px!important}.iq-combo-promo-steps--text-pad-small,.iq-combo-promo-steps--text-pad-small-right{padding-right:20px!important}}
.iq-combo-promo-steps--text{font-family:Helvetica!important;font-size:18px;color:#393a44;letter-spacing:0;line-height:26px;font-weight:400}
.iq-combo-promo-steps--promocode{font-family:Helvetica!important;font-style:normal;background:#ffefe0;border:2px dashed #f70;border-radius:16px;padding:16px 22px;color:#f70;font-size:24px;font-weight:700;line-height:31px}
.iq-combo-promo-steps--small-gray-text{font-family:Helvetica!important;font-style:normal;font-weight:400;font-size:16px;line-height:24px;color:#84868b}
.iq-combo-promo-steps--w280{width:100%;max-width:280px}
@media screen and (max-width:600px){.iq-combo-promo-steps--w280{max-width:100%!important}}
.iq-combo-promo-steps--butt{background-color:#f70;border-radius:16px!important;font-size:18px!important;font-weight:700!important;font-family:Helvetica!important;height:auto}
.iq-combo-promo-steps--butt-link{font-size:18px;font-weight:700;text-decoration:none;color:#f9f9f9;display:block;line-height:27px;padding:16px 0;text-align:center}

/* втянуто из стилей семьи при скоупе — блок больше не зависит от main.styl */
.iq-combo-promo-steps--pb44{padding-bottom:44px}
.iq-combo-promo-steps--pt44{padding-top:44px}
.iq-combo-promo-steps--pb32{padding-bottom:32px}
.iq-combo-promo-steps--pt24{padding-top:24px}
.iq-combo-promo-steps--pb5{padding-bottom:5px}
.iq-combo-promo-steps--pt5{padding-top:5px}
